import type { Metadata } from "next";
import { site } from "@/content/site";
import { ogSize } from "@/lib/og";

/**
 * Next.js replaces (not merges) `openGraph` and `twitter` when a page sets them,
 * so pages spread these bases to keep site name, locale and card type.
 */
export const baseOpenGraph = {
  siteName: site.name,
  locale: "en_US",
} satisfies Metadata["openGraph"];

export const baseTwitter = {
  card: "summary_large_image",
} satisfies Metadata["twitter"];

/**
 * Share image generated by app/og/[file]/route.tsx. Real .png files, because static
 * hosts such as GitHub Pages serve extension-less files as application/octet-stream.
 */
export function ogImage(name: string, alt: string) {
  return { url: `/og/${name}.png`, ...ogSize, alt, type: "image/png" };
}
